            if (modifiers && modifiers[subPath]) {
                obj1[key] = modifiers[subPath](obj1[key], obj2[key]);
            } else {
                obj1[key] = collideUnsafe(obj1[key], obj2[key], modifiers, subPath);
            }
        }
    }

    return obj1;
}
